template <class I>

concept /*decrementable*/ =

    std::incrementable<I> && requires(I i) {
        { --i } -> std::same_as<I &>;

        { i-- } -> std::same_as<I>;
    };

template <class I>

concept /*advanceable*/ =

    /*decrementable*/<I> && std::totally_ordered<I> &&

    requires(I i, const I j, const /*iota-diff-t*/<I> n) {
        { i += n } -> std::same_as<I &>;

        { i -= n } -> std::same_as<I &>;

        I(j + n);

        I(n + j);

        I(j - n);

        { j - j } -> std::convertible_to</*iota-diff-t*/<I>>;
    };

