std::ranges::iota_view::iterator::operator*



 constexpr W operator*() const

    noexcept(std::is_nothrow_copy_constructible_v<W>);

 (since C++20) 



Returns value_.

 Example

#include <cassert>
#include <ranges>

int main()
{
    auto it{std::views::iota(6, 9).begin()};
    const int& r = *it; // binds with temporary
    assert(*it == 6 and r == 6);
    ++it;
    assert(*it == 7 and r == 6);
}

